import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

/**
 * Test the successful renewal of authentication tokens for an existing member session.
 *
 * Validates that a valid refresh token can be used to obtain new access and refresh tokens without requiring re-authentication. Ensures that the member identity is correctly preserved across the token refresh operation and that new tokens are generated with updated expiration timestamps.
 *
 * 1. Register a new member account and obtain initial access and refresh tokens.
 * 2. Store the original refresh token and member identity from the join response.
 * 3. Use the refresh token to call the token refresh endpoint.
 * 4. Verify that new access and refresh tokens are generated and differ from the originals.
 * 5. Confirm that member identity (id, email, display_name, created_at, updated_at, deleted_at) is correctly returned.
 * 6. Validate that token expiration timestamps (expired_at, refreshable_until) are present and valid.
 */
export async function test_api_member_refresh_successful_token_renewal(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new member account and obtain initial tokens
  const memberConnection: api.IConnection = { host: connection.host };
  const joinResponse = await authorize_member_join(memberConnection, {
    body: {},
  });
  typia.assert(joinResponse);
  // Store original tokens and identity for comparison
  const originalAccessToken = joinResponse.token.access;
  const originalRefreshToken = joinResponse.token.refresh;
  const originalMemberId = joinResponse.id;
  const originalEmail = joinResponse.email;
  const originalDisplayName = joinResponse.display_name;
  const originalCreatedAt = joinResponse.created_at;
  const originalUpdatedAt = joinResponse.updated_at;
  const originalDeletedAt = joinResponse.deleted_at;
  // 2. Create a new connection for refresh operation
  const refreshConnection: api.IConnection = { host: connection.host };
  // 3. Call refresh endpoint with the original refresh token
  const refreshResponse = await authorize_member_refresh(refreshConnection, {
    body: {
      refreshToken: originalRefreshToken,
    } satisfies ITodoAppMember.IRefresh,
  });
  typia.assert(refreshResponse);
  // 4. Validate that new tokens are generated and different from originals
  TestValidator.notEquals(
    "access token should be renewed",
    originalAccessToken,
    refreshResponse.token.access,
  );
  TestValidator.notEquals(
    "refresh token should be renewed",
    originalRefreshToken,
    refreshResponse.token.refresh,
  );
  // 5. Validate that member identity is preserved
  TestValidator.equals(
    "member id should be preserved",
    originalMemberId,
    refreshResponse.id,
  );
  TestValidator.equals(
    "member email should be preserved",
    originalEmail,
    refreshResponse.email,
  );
  TestValidator.equals(
    "member display_name should be preserved",
    originalDisplayName,
    refreshResponse.display_name,
  );
  TestValidator.equals(
    "member created_at should be preserved",
    originalCreatedAt,
    refreshResponse.created_at,
  );
  TestValidator.equals(
    "member updated_at should be preserved",
    originalUpdatedAt,
    refreshResponse.updated_at,
  );
  TestValidator.equals(
    "member deleted_at should be preserved",
    originalDeletedAt,
    refreshResponse.deleted_at,
  );
  // 6. Validate that token expiration timestamps are present
  TestValidator.predicate(
    "expired_at should be present",
    refreshResponse.token.expired_at !== undefined &&
      refreshResponse.token.expired_at !== null,
  );
  TestValidator.predicate(
    "refreshable_until should be present",
    refreshResponse.token.refreshable_until !== undefined &&
      refreshResponse.token.refreshable_until !== null,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

/**
 * Test token refresh operation maintains session context and extends session lifetime.
 *
 * Validates that the member refresh endpoint correctly extends the authentication session while preserving member identity. The test verifies that refreshed tokens have extended expiration times and that all member profile data remains consistent across refresh operations.
 *
 * Special attention is given to ensuring that the session extension mechanism works correctly, with the new expired_at timestamp being later than the original, and that the refreshable_until deadline properly represents the absolute session expiration boundary.
 *
 * 1. Register a new member account to obtain initial authentication tokens.
 * 2. Extract the refresh token and initial expired_at timestamp from the join response.
 * 3. Create a new connection for the refresh operation following connection isolation pattern.
 * 4. Call the refresh endpoint with the refresh token.
 * 5. Validate that the new expired_at is later than the original expired_at.
 * 6. Confirm member identity (id, email) remains consistent across operations.
 * 7. Verify all required fields are present in both responses.
 */
export async function test_api_member_refresh_with_valid_session_context(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new member to create initial session
  const memberConnection: api.IConnection = { host: connection.host };
  const initialAuth: ITodoAppMember.IAuthorized =
    await api.functional.todoApp.auth.member.join(memberConnection, {
      body: typia.random<ITodoAppMember.IJoin>(),
    });
  typia.assert(initialAuth);
  // 2. Extract refresh token and initial timestamps
  const refreshToken: string = initialAuth.token.refresh;
  const initialExpiredAt: Date = new Date(initialAuth.token.expired_at);
  const initialMemberId: string = initialAuth.id;
  const initialEmail: string = initialAuth.email;
  // 3. Create new connection for refresh operation (connection isolation)
  const refreshConnection: api.IConnection = { host: connection.host };
  // 4. Call refresh endpoint with the refresh token
  const refreshedAuth: ITodoAppMember.IAuthorized =
    await api.functional.todoApp.auth.member.refresh(refreshConnection, {
      body: {
        refreshToken,
      } satisfies ITodoAppMember.IRefresh,
    });
  typia.assert(refreshedAuth);
  // 5. Validate that new expired_at is later than original (session extended)
  const refreshedExpiredAt: Date = new Date(refreshedAuth.token.expired_at);
  TestValidator.predicate(
    "session extended - new expired_at is later than initial",
    refreshedExpiredAt.getTime() > initialExpiredAt.getTime(),
  );
  // 6. Confirm member identity remains consistent across refresh
  TestValidator.equals(
    "member id unchanged",
    refreshedAuth.id,
    initialMemberId,
  );
  TestValidator.equals(
    "member email unchanged",
    refreshedAuth.email,
    initialEmail,
  );
  // 7. Validate refreshable_until represents absolute session expiration deadline
  TestValidator.predicate(
    "refreshable_until is in the future",
    new Date(refreshedAuth.token.refreshable_until).getTime() > Date.now(),
  );
  // 8. Verify that new access and refresh tokens are different (token rotation)
  TestValidator.notEquals(
    "access token refreshed",
    refreshedAuth.token.access,
    initialAuth.token.access,
  );
  TestValidator.notEquals(
    "refresh token refreshed",
    refreshedAuth.token.refresh,
    initialAuth.token.refresh,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMember";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test retrieving a paginated list of active (non-deleted) member accounts.
 *
 * Validates the member listing endpoint returns correct pagination metadata and member summaries for active accounts. Ensures that soft-deleted members are excluded by default and that all required fields are present in the response.
 *
 * Special attention is given to verifying that deleted_at is null for all active members and that pagination metadata accurately reflects the total count and page navigation.
 *
 * 1. Call PATCH /todoApp/members with default parameters to retrieve all active members.
 * 2. Verify response contains pagination metadata (current, limit, records, pages).
 * 3. Verify each member summary contains required fields and deleted_at is null.
 * 4. Test pagination by requesting specific page and limit values.
 * 5. Verify pagination metadata reflects correct current page and total pages.
 * 6. Verify paginated members are distinct across pages.
 */
export async function test_api_member_list_active_members(
  connection: api.IConnection,
): Promise<void> {
  // 1. Retrieve all active members with default parameters
  const allMembers = await api.functional.todoApp.members.index(connection, {
    body: {} satisfies ITodoAppMember.IRequest,
  });
  typia.assert(allMembers);
  // 2. Verify pagination metadata has valid values
  TestValidator.predicate(
    "pagination current page is at least 1",
    allMembers.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit is positive",
    allMembers.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "pagination records count is non-negative",
    allMembers.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages count is non-negative",
    allMembers.pagination.pages >= 0,
  );
  // 3. Verify all returned members are active (deleted_at = null)
  for (const member of allMembers.data) {
    TestValidator.equals(
      `member ${member.id} is active (deleted_at is null)`,
      member.deleted_at,
      null,
    );
  }
  // 4. Test pagination with specific limit
  const paginatedMembers = await api.functional.todoApp.members.index(
    connection,
    {
      body: {
        limit: 2,
        page: 1,
      } satisfies ITodoAppMember.IRequest,
    },
  );
  typia.assert(paginatedMembers);
  // 5. Verify pagination respects limit
  TestValidator.predicate(
    "paginated data length does not exceed limit",
    paginatedMembers.data.length <= paginatedMembers.pagination.limit,
  );
  TestValidator.equals(
    "pagination current page is 1",
    paginatedMembers.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit is 2",
    paginatedMembers.pagination.limit,
    2,
  );
  // 6. Verify all paginated members are also active
  for (const member of paginatedMembers.data) {
    TestValidator.equals(
      `paginated member ${member.id} is active`,
      member.deleted_at,
      null,
    );
  }
  // 7. Test page 2 pagination (if enough records exist)
  if (allMembers.pagination.pages >= 2) {
    const page2Members = await api.functional.todoApp.members.index(
      connection,
      {
        body: {
          limit: 2,
          page: 2,
        } satisfies ITodoAppMember.IRequest,
      },
    );
    typia.assert(page2Members);
    TestValidator.equals(
      "page 2 current page is 2",
      page2Members.pagination.current,
      2,
    );
    // Verify page 2 members are different from page 1
    const page1Ids = new Set(paginatedMembers.data.map((m) => m.id));
    for (const member of page2Members.data) {
      TestValidator.predicate(
        `page 2 member ${member.id} is not in page 1`,
        !page1Ids.has(member.id),
      );
      TestValidator.equals(
        `page 2 member ${member.id} is active`,
        member.deleted_at,
        null,
      );
    }
  }
  // 8. Verify pagination consistency: records should match expected calculation
  TestValidator.predicate(
    "total records is consistent with pages calculation",
    allMembers.pagination.records === 0
      ? allMembers.pagination.pages === 0
      : allMembers.pagination.pages ===
          Math.ceil(
            allMembers.pagination.records / allMembers.pagination.limit,
          ),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMember";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

/**
 * Test searching and filtering member accounts by various criteria.
 *
 * Validates the member list search and filtering functionality including case-insensitive partial matching on email and display name fields, date range filtering, sorting by multiple fields, and pagination. Ensures that the search performs correctly across different filter combinations and that pagination metadata accurately reflects the result set.
 *
 * Special attention is given to verifying that search is case-insensitive, date range filters correctly narrow results, and sorting works for all supported fields (email, display_name, created_at, updated_at).
 *
 * 1. Test basic member list retrieval with default parameters.
 * 2. Test search by email with partial matching.
 * 3. Test search by display name with case-insensitive matching.
 * 4. Test date range filtering with created_at_from and created_at_to.
 * 5. Test sorting by email in ascending order.
 * 6. Test sorting by created_at in descending order.
 * 7. Test pagination with custom page and limit values.
 * 8. Test include_deleted flag to include soft-deleted members.
 * 9. Validate response structure and pagination metadata accuracy.
 */
export async function test_api_member_list_search_and_filter(
  connection: api.IConnection,
): Promise<void> {
  // 1. Test basic member list retrieval with default parameters
  const defaultList = await api.functional.todoApp.members.index(connection, {
    body: {} satisfies ITodoAppMember.IRequest,
  });
  typia.assert(defaultList);
  TestValidator.equals("default pagination exists", defaultList.pagination, {
    current: defaultList.pagination.current,
    limit: defaultList.pagination.limit,
    records: defaultList.pagination.records,
    pages: defaultList.pagination.pages,
  });
  // 2. Test search by email with partial matching
  const emailSearch = await api.functional.todoApp.members.index(connection, {
    body: {
      search: "@",
    } satisfies ITodoAppMember.IRequest,
  });
  typia.assert(emailSearch);
  TestValidator.predicate(
    "email search returns results",
    emailSearch.data.length >= 0,
  );
  // Verify all returned members have email containing "@"
  await ArrayUtil.asyncForEach(emailSearch.data, async (member) => {
    TestValidator.predicate(
      `member ${member.id} email contains @`,
      member.email.includes("@"),
    );
  });
  // 3. Test search by display name with case-insensitive matching
  const nameSearch = await api.functional.todoApp.members.index(connection, {
    body: {
      search: "a", // Common letter to find some members
    } satisfies ITodoAppMember.IRequest,
  });
  typia.assert(nameSearch);
  TestValidator.predicate(
    "name search returns results",
    nameSearch.data.length >= 0,
  );
  // Verify all returned members have email or display_name containing "a" (case-insensitive)
  await ArrayUtil.asyncForEach(nameSearch.data, async (member) => {
    const matchesEmail = member.email.toLowerCase().includes("a");
    const matchesName =
      member.display_name?.toLowerCase().includes("a") ?? false;
    TestValidator.predicate(
      `member ${member.id} matches search criteria`,
      matchesEmail || matchesName,
    );
  });
  // 4. Test date range filtering with created_at_from and created_at_to
  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
  const dateFilter = await api.functional.todoApp.members.index(connection, {
    body: {
      created_at_from: oneYearAgo.toISOString(),
      created_at_to: new Date().toISOString(),
    } satisfies ITodoAppMember.IRequest,
  });
  typia.assert(dateFilter);
  TestValidator.predicate(
    "date filter returns results",
    dateFilter.data.length >= 0,
  );
  // Verify all returned members were created within the date range
  await ArrayUtil.asyncForEach(dateFilter.data, async (member) => {
    const createdAt = new Date(member.created_at);
    TestValidator.predicate(
      `member ${member.id} created_at within range`,
      createdAt >= oneYearAgo && createdAt <= new Date(),
    );
  });
  // 5. Test sorting by email in ascending order
  const emailSortAsc = await api.functional.todoApp.members.index(connection, {
    body: {
      sort_by: "email",
      sort_order: "asc",
      limit: 100,
