    customLimit.data.length <= 5,
  );
  // 6. Test with custom sort order (ascending)
  const ascendingOrder =
    await api.functional.todoApp.member.member.password_resets.index(
      memberConnection,
      {
        body: {
          order: "asc",
          sort: "created_at",
        } satisfies ITodoAppMemberPasswordReset.IRequest,
